package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import javax.sql.DataSource;
import org.springframework.beans.factory.config.BeanPostProcessor;
import org.springframework.jdbc.datasource.DelegatingDataSource;
import org.springframework.stereotype.Component;

/**
 * Every connection is handed out reading the store as it stands now, or, for a request reading the sheet as of a date
 * ({@link AsOfView}), reading that date's schema with the date as the sheet's today. Set on every hand-out, so a
 * pooled connection never passes one request's view on to the next.
 */
@Component
public class AsOfConnections implements BeanPostProcessor {

    @Override
    public Object postProcessAfterInitialization(Object bean, String beanName) {
        if (bean instanceof DataSource dataSource && !(bean instanceof DelegatingDataSource)) {
            return new DelegatingDataSource(dataSource) {
                @Override
                public Connection getConnection() throws SQLException {
                    return viewed(super.getConnection());
                }

                @Override
                public Connection getConnection(String username, String password) throws SQLException {
                    return viewed(super.getConnection(username, password));
                }
            };
        }
        return bean;
    }

    private static Connection viewed(Connection connection) throws SQLException {
        AsOfView view = AsOfView.current();
        try (Statement s = connection.createStatement()) {
            if (view == null) {
                s.execute("SET SCHEMA PUBLIC");
                s.execute("SET @asof = NULL");
            } else {
                s.execute("SET SCHEMA " + view.schema());
                s.execute("SET @asof = DATE '" + view.date() + "'");
            }
        }
        return connection;
    }
}
package net.officefloor.hq.app.asof;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A read of a sheet ({@code GET /api/sheets/<id>...}) with {@code ?asOf=<yyyy-MM-dd>} reads the whole sheet as it
 * stood at the end of the last day on or before that date ({@link SheetDayRepository#schemaAsOf}), with the date
 * standing in for the sheet's today: every endpoint reads it unchanged, as every connection the request takes is
 * pointed at that sheet. Only reads are viewed so; a change is never made as of a date.
 * <p>
 * A read with {@code ?preview=<yyyy-MM-dd>} (and no {@code asOf}) reads the sheet's current records with the date
 * standing in for its today: a preview of its figures on that date. A change always uses the sheet's real today.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class AsOfFilter extends OncePerRequestFilter {

    private static final Pattern SHEET_READ = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final SheetDayRepository days;

    public AsOfFilter(SheetDayRepository days) {
        this.days = days;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String asOf = request.getParameter("asOf");
        boolean preview = asOf == null || asOf.isBlank();
        if (preview) {
            asOf = request.getParameter("preview");
        }
        Matcher read = SHEET_READ.matcher(request.getRequestURI());
        if (!"GET".equals(request.getMethod()) || asOf == null || asOf.isBlank() || !read.matches()) {
            AsOfView.set(null);
            chain.doFilter(request, response);
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(asOf.trim());
        } catch (DateTimeParseException e) {
            response.sendError(HttpStatus.BAD_REQUEST.value(), "Not a date: " + asOf);
            return;
        }
        String sheetId = URLDecoder.decode(read.group(1), StandardCharsets.UTF_8);
        AsOfView.set(null);
        String schema = preview ? days.liveSchema() : days.schemaAsOf(sheetId, date);
        AsOfView.set(new AsOfView(schema, date, preview));
        try {
            chain.doFilter(request, response);
        } finally {
            AsOfView.set(null);
        }
    }
}
package net.officefloor.hq.app.asof;

import java.time.LocalDate;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.Supplier;
import org.springframework.stereotype.Component;

/**
 * Reads the sheet as it stood at the end of a date ({@link AsOfView}), with the date standing in for its today, from
 * within a request that changes the store now: the read runs on a thread of its own, outside the request's
 * transaction, so every connection it takes is pointed at that date's schema, exactly as a read of the as-of view is.
 */
@Component
public class AsOfReader {

    private final SheetDayRepository days;
    private final ExecutorService threads = Executors.newCachedThreadPool((r) -> {
        Thread t = new Thread(r, "as-of-read");
        t.setDaemon(true);
        return t;
    });

    public AsOfReader(SheetDayRepository days) {
        this.days = days;
    }

    /** The read's result, made against the sheet as it stood at the end of the date. */
    public <T> T read(String sheetId, LocalDate date, Supplier<T> read) {
        String schema = days.schemaAsOf(sheetId, date);
        try {
            return threads.submit(() -> {
                AsOfView.set(new AsOfView(schema, date));
                try {
                    return read.get();
                } finally {
                    AsOfView.set(null);
                }
            }).get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("Interrupted reading sheet " + sheetId + " as of " + date, e);
        } catch (ExecutionException e) {
            throw e.getCause() instanceof RuntimeException r ? r
                    : new IllegalStateException("Could not read sheet " + sheetId + " as of " + date, e.getCause());
        }
    }
}
package net.officefloor.hq.app.asof;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import javax.sql.DataSource;
import net.officefloor.hq.app.rate.RateRepository;
import org.springframework.stereotype.Component;

/**
 * The schemas a sheet is read from as of a date. Each holds every table the app keeps (under its own name, so every
 * repository reads it unchanged once a request's connection is switched to it), with {@code sheet} a view whose today
 * is the session's {@code @asof} date:
 * <ul>
 * <li>a snapshot: a copy of the sheet's rows (and its pools' members, and the rates of the sheets above it it
 * inherits rates from) as they stood at a moment;</li>
 * <li>{@link #LIVE}: the sheet as it stands now;</li>
 * <li>{@link #EMPTY}: nothing on the sheet yet (every setting at its default).</li>
 * </ul>
 * Schemas are made on connections of their own (H2 commits DDL), never on a request's transaction.
 */
@Component
public class AsOfSchemas {

    public static final String LIVE = "ASOF_LIVE";
    public static final String EMPTY = "ASOF_EMPTY";

    private static final String SHEET = "SHEET";
    private static final List<String> NOT_COPIED = List.of("SHEET_DAY", "flyway_schema_history");
    /** The tables also copied for the sheets above it, so the rates it inherits read as they stood. */
    private static final List<String> INHERITED = List.of("RATE", "RATE_VERSION");

    private final DataSource dataSource;
    private boolean shared;

    public AsOfSchemas(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    /** Copy every row kept for the sheet, as committed now, into a new schema; its name. */
    public String snapshot(String sheetId) {
        String schema = "ASOF_" + UUID.randomUUID().toString().replace("-", "").toUpperCase();
        String id = literal(sheetId);
        try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
            c.setAutoCommit(true);
            String inherited = String.join(", ", lineage(c, sheetId).stream().map(AsOfSchemas::literal).toList());
            s.execute("CREATE SCHEMA " + schema);
            for (String table : tables(c)) {
                s.execute("CREATE TABLE " + schema + "." + q(table) + " AS SELECT * FROM PUBLIC." + q(table)
                        + " WHERE SHEET_ID " + (INHERITED.contains(table) ? "IN (" + inherited + ")" : "= " + id));
            }
            for (String table : poolTables(c)) {
                s.execute("CREATE TABLE " + schema + "." + q(table) + " AS SELECT * FROM PUBLIC." + q(table)
                        + " WHERE POOL_ID IN (SELECT ID FROM PUBLIC.POOL WHERE SHEET_ID = " + id + ")");
            }
            s.execute("CREATE TABLE " + schema + ".SHEET_DATA AS SELECT * FROM PUBLIC.SHEET WHERE ID = " + id);
            s.execute("CREATE VIEW " + schema + ".SHEET AS SELECT " + sheetColumns(c, false) + " FROM " + schema
                    + ".SHEET_DATA s");
        } catch (SQLException e) {
